import { useMemo, useState } from 'react';
import { base44 } from '@/api/base44Client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { KeyRound, Loader2, CheckCircle2 } from 'lucide-react';
import AuthLayout from '@/components/AuthLayout';
import {
  resetSubmitResult,
  validateNewPassword,
  readResetToken,
} from '@/lib/passwordResetMessages';

// MindVault-branded "set a new password". The reset link is generated by
// Base44's email (whose target URL / param name we cannot control), so this
// screen accepts the code as either ?token= or ?reset_token= and calls
// Base44's supported resetPassword(). The token is never logged.

export default function ResetPassword() {
  const token = useMemo(() => readResetToken(window.location.search), []);
  const [pw, setPw] = useState('');
  const [confirm, setConfirm] = useState('');
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState('');

  if (!token) {
    return (
      <AuthLayout icon={KeyRound} title="Reset link incomplete" subtitle="MindVault">
        <p className="text-sm text-muted-foreground text-center">
          This link is missing its reset code. Request a fresh link from the “Forgot password”
          screen.
        </p>
        <Button asChild variant="outline" className="mt-6 w-full">
          <a href="/forgot-password">Request a new link</a>
        </Button>
      </AuthLayout>
    );
  }

  if (done) {
    return (
      <AuthLayout icon={CheckCircle2} title="Password updated" subtitle="MindVault">
        <p className="text-sm text-muted-foreground text-center">
          Your password has been updated. You can sign in now.
        </p>
        <Button asChild className="mt-6 w-full">
          <a href="/">Go to MindVault</a>
        </Button>
      </AuthLayout>
    );
  }

  const submit = async (e) => {
    e.preventDefault();
    setError('');
    const rule = validateNewPassword(pw, confirm);
    if (rule) {
      setError(rule);
      return;
    }
    setBusy(true);
    try {
      await base44.auth.resetPassword({ resetToken: token, newPassword: pw });
      const r = resetSubmitResult({ resolved: true });
      if (r.ok) setDone(true);
      else setError(r.message);
    } catch (err) {
      const status = err?.response?.status || err?.status;
      setError(resetSubmitResult({ resolved: false, status }).message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <AuthLayout icon={KeyRound} title="Set a new password" subtitle="MindVault">
      <form onSubmit={submit} className="space-y-4">
        {error ? (
          <div className="p-3 rounded-lg bg-destructive/10 text-destructive text-sm">{error}</div>
        ) : null}
        <div className="space-y-1.5">
          <Label htmlFor="pw" className="text-sm">
            New password
          </Label>
          <Input
            id="pw"
            type="password"
            value={pw}
            onChange={(e) => setPw(e.target.value)}
            autoComplete="new-password"
            placeholder="At least 8 characters"
            required
          />
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="confirm" className="text-sm">
            Confirm new password
          </Label>
          <Input
            id="confirm"
            type="password"
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
            autoComplete="new-password"
            placeholder="Re-enter the password"
            required
          />
        </div>
        <Button type="submit" className="w-full h-11" disabled={busy || !pw || !confirm}>
          {busy ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
          Update password
        </Button>
      </form>
    </AuthLayout>
  );
}
